package by.bsuir.insurance.server.logic;

/** Фабрика стратегий расчёта премии (паттерн «Фабрика»). */
public final class PremiumStrategyFactory {
    private static final Map<InsuranceCategory, PremiumStrategy> STRATEGIES = new EnumMap<>(InsuranceCategory.class);

    static {
        STRATEGIES.put(InsuranceCategory.PROPERTY, new PropertyPremiumStrategy());
        STRATEGIES.put(InsuranceCategory.CASCO, new CascoPremiumStrategy());
        STRATEGIES.put(InsuranceCategory.ACCIDENT, new AccidentPremiumStrategy());
        STRATEGIES.put(InsuranceCategory.TRAVEL, new TravelPremiumStrategy());
    }

    private PremiumStrategyFactory() {
    }

    public static PremiumStrategy forType(InsuranceType type) {
        PremiumStrategy strategy = STRATEGIES.get(type.getCategory());
        if (strategy == null) {
            throw new IllegalArgumentException("Нет стратегии для категории " + type.getCategory());
        }
        return strategy;
    }
}

package by.bsuir.insurance.server.logic;

/** Формирование графика страховых взносов. */
public final class InstallmentScheduler {

    private InstallmentScheduler() {
    }

    public static void validate(int termMonths, int installments) throws ValidationException {
        if (installments != 1 && installments != 2 && installments != 4 && installments != 12) {
            throw new ValidationException("Число взносов может быть 1, 2, 4 или 12");
        }
        if (installments > termMonths || termMonths % installments != 0) {
            throw new ValidationException("Срок " + termMonths + " мес. нельзя разделить на " + installments + " равных взносов");
        }
    }

    /**
     * Делит премию на равные взносы; копейки, оставшиеся от деления, добавляются к последнему взносу.
     * Первый взнос — в дату начала договора, следующие — через равные интервалы.
     */
    public static List<Payment> build(long policyId, BigDecimal premium, int installments,
                                      LocalDate startDate, int termMonths) throws ValidationException {
        validate(termMonths, installments);
        int stepMonths = termMonths / installments;
        BigDecimal base = premium.divide(new BigDecimal(installments), 2, RoundingMode.DOWN);
        List<Payment> list = new ArrayList<>();
        for (int i = 1; i <= installments; i++) {
            BigDecimal amount = i < installments
                    ? base : premium.subtract(base.multiply(new BigDecimal(installments - 1)));
            list.add(new Payment(policyId, i, amount, startDate.plusMonths((long) stepMonths * (i - 1))));
        }
        return list;
    }
}

package by.bsuir.insurance.server.logic;

/**
 * Алгоритм расчёта страховой выплаты (функция A44 модели IDEF0).
 */
public class PayoutCalculator {
    /** Максимальный срок подачи заявления, дней. */
    public static final int REPORT_DEADLINE_DAYS = 30;

    /**
     * @param policy       договор
     * @param payments     график взносов договора
     * @param claim        страховой случай
     * @param damage       оценённый агентом размер ущерба
     * @param paidBefore   сумма выплат по договору до этого случая
     */
    public PayoutDecision calculate(Policy policy, List<Payment> payments, Claim claim,
                                    BigDecimal damage, BigDecimal paidBefore) {
        List<String> steps = new ArrayList<>();
        LocalDate incident = claim.getIncidentDate();

        // 1. Договор действовал на дату события
        steps.add("Период действия договора: " + policy.getStartDate() + " – " + policy.getEndDate());
        if (!policy.isActiveOn(incident)) {
            return PayoutDecision.reject("событие произошло вне периода действия договора", steps);
        }
        LocalDateTime terminatedAt = policy.getTerminatedAt();
        if (terminatedAt != null && !incident.isBefore(terminatedAt.toLocalDate())) {
            return PayoutDecision.reject("договор был расторгнут до даты события", steps);
        }
        // 2. Нет просроченных взносов на дату события
        for (Payment p : payments) {
            if (p.isOverdue(incident)) {
                steps.add("Взнос № " + p.getInstallmentNo() + " со сроком " + p.getDueDate() + " не был уплачен");
                return PayoutDecision.reject("на дату события имелись просроченные страховые взносы", steps);
            }
        }
        steps.add("Просроченных взносов на дату события нет");
        // 3. Срок подачи заявления
        long days = ChronoUnit.DAYS.between(incident, claim.getReportDate());
        steps.add("Заявление подано через " + days + " дн. после события");
        if (days > REPORT_DEADLINE_DAYS) {
            return PayoutDecision.reject("заявление подано позднее " + REPORT_DEADLINE_DAYS + " дней с даты события", steps);
        }
        // 4. Франшиза
        BigDecimal franchise = Money.nz(policy.getFranchise());
        steps.add("Ущерб " + Money.format(damage) + ", франшиза " + Money.format(franchise));
        if (damage.compareTo(franchise) <= 0) {
            return PayoutDecision.reject("размер ущерба не превышает франшизу", steps);
        }
        BigDecimal payout = damage.subtract(franchise);
        // 5. Ограничение остатком страховой суммы
        BigDecimal remaining = policy.getInsuredSum().subtract(Money.nz(paidBefore));
        steps.add("Остаток страховой суммы: " + Money.format(remaining));
        if (remaining.signum() <= 0) {
            return PayoutDecision.reject("страховая сумма исчерпана предыдущими выплатами", steps);
        }
        boolean exhausts = false;
        if (payout.compareTo(remaining) >= 0) {
            payout = remaining;
            exhausts = true;
            steps.add("Выплата ограничена остатком страховой суммы, договор будет исполнен");
        }
        payout = Money.round(payout);
        steps.add("Сумма выплаты: " + Money.format(payout));
        return PayoutDecision.approve(payout, exhausts, steps);
    }
}

package by.bsuir.insurance.server.logic;

/**
 * Возврат части премии при досрочном расторжении:
 * В = уплачено × (неистёкшие дни / все дни) × (1 − доля расходов) − выплаты, но не меньше 0.
 */
public class RefundCalculator {
    /** Доля расходов на ведение дела, удерживаемая страховщиком. */
    public static final BigDecimal EXPENSES_SHARE = new BigDecimal("0.25");

    public RefundCalculation calculate(Policy policy, BigDecimal paid, BigDecimal payouts, LocalDate terminationDate) {
        long total = ChronoUnit.DAYS.between(policy.getStartDate(), policy.getEndDate()) + 1;
        long remaining = ChronoUnit.DAYS.between(terminationDate, policy.getEndDate());
        if (terminationDate.isBefore(policy.getStartDate())) {
            remaining = total;
        }
        remaining = Math.max(0, Math.min(total, remaining));
        BigDecimal refund = Money.nz(paid)
                .multiply(new BigDecimal(remaining))
                .divide(new BigDecimal(total), MathContext.DECIMAL64)
                .multiply(BigDecimal.ONE.subtract(EXPENSES_SHARE))
                .subtract(Money.nz(payouts));
        if (refund.signum() < 0) {
            refund = BigDecimal.ZERO;
        }
        return new RefundCalculation(Money.nz(paid), total, remaining, EXPENSES_SHARE, Money.nz(payouts), Money.round(refund));
    }
}

