/** Правила автоматической смены состояний договора (см. диаграмму состояний). */
public final class PolicyStatusRules {
    /** Срок оплаты первого взноса после оформления, дней. */
    public static final int FIRST_PAYMENT_DAYS = 10;
    /** Допустимая просрочка очередного взноса до расторжения, дней. */
    public static final int MAX_OVERDUE_DAYS = 30;

    private PolicyStatusRules() {
    }

    /** Новое состояние договора на дату today (или текущее, если переход не нужен). */
    public static PolicyStatus evaluate(Policy policy, List<Payment> payments, LocalDate today) {
        PolicyStatus status = policy.getStatus();
        if (status == PolicyStatus.TERMINATED || status == PolicyStatus.FULFILLED || status == PolicyStatus.EXPIRED) {
            return status;
        }
        if (status == PolicyStatus.WAITING_PAYMENT) {
            Payment first = payments.isEmpty() ? null : payments.get(0);
            if (first != null && first.isPaid()) {
                return PolicyStatus.ACTIVE;
            }
            LocalDate created = policy.getCreatedAt().toLocalDate();
            return ChronoUnit.DAYS.between(created, today) > FIRST_PAYMENT_DAYS ? PolicyStatus.TERMINATED : status;
        }
        if (today.isAfter(policy.getEndDate())) {
            return PolicyStatus.EXPIRED;
        }
        long maxOverdue = 0;
        for (Payment p : payments) {
            if (p.isOverdue(today)) {
                maxOverdue = Math.max(maxOverdue, ChronoUnit.DAYS.between(p.getDueDate(), today));
            }
        }
        if (maxOverdue > MAX_OVERDUE_DAYS) {
            return PolicyStatus.TERMINATED;
        }
        return maxOverdue > 0 ? PolicyStatus.SUSPENDED : PolicyStatus.ACTIVE;
    }
}

package by.bsuir.insurance.server.service;

/** Расчёт стоимости, заявки и оформление договоров по заявкам. */
public class ApplicationService {
    private final ApplicationDao applicationDao = new ApplicationDao();
    private final InsuranceTypeDao typeDao = new InsuranceTypeDao();
    private final ClientDao clientDao = new ClientDao();
    private final ClaimDao claimDao = new ClaimDao();
    private final PolicyDao policyDao = new PolicyDao();
    private final PaymentDao paymentDao = new PaymentDao();
    private final PremiumCalculator calculator = new PremiumCalculator();
    private final ConnectionManager cm = ConnectionManager.getInstance();

    /** Расчёт стоимости страхования для клиента (UC3). */
    public PremiumQuote quote(long clientId, Application a, LocalDate startDate) throws Exception {
        return cm.withConnection(c -> quote(c, clientId, a, startDate));
    }

    private PremiumQuote quote(Connection c, long clientId, Application a, LocalDate startDate) throws Exception {
        InsuranceType type = typeDao.findById(c, a.getTypeId());
        if (type == null) {
            throw new ValidationException("Вид страхования не найден");
        }
        Client client = clientDao.findById(c, clientId);
        int claims = claimDao.countPaidClaims(c, clientId, startDate.minusYears(2), startDate);
        return calculator.calculate(type, a, client, startDate, claims);
    }

    /** Подача заявки клиентом (UC4). Параметры проверяются тем же калькулятором. */
    public Application submit(long clientId, Application a) throws Exception {
        a.setClientId(clientId);
        a.setObjectDescription(Validator.required(a.getObjectDescription(), "Описание объекта страхования"));
        return cm.inTransaction(c -> {
            quote(c, clientId, a, LocalDate.now().plusDays(1));
            long id = applicationDao.insert(c, a);
            return applicationDao.findById(c, id);
        });
    }

    public ArrayList<Application> listByClient(long clientId) throws Exception {
        return new ArrayList<>(cm.withConnection(c -> applicationDao.listByClient(c, clientId)));
    }

    /** Новые заявки с предварительным расчётом премии. */
    public ArrayList<Application> listNew() throws Exception {
        return cm.withConnection(c -> {
            List<Application> list = applicationDao.listByStatus(c, ApplicationStatus.NEW);
            for (Application a : list) {
                try {
                    a.setEstimatedPremium(quote(c, a.getClientId(), a, LocalDate.now().plusDays(1)).getPremium());
                } catch (ValidationException e) {
                    a.setEstimatedPremium(null);
                }
            }
            return new ArrayList<>(list);
        });
    }

    /**
     * Одобрение заявки и оформление договора (UC5): в одной транзакции рассчитывается премия,
     * создаются договор и график взносов, заявка переводится в статус «Одобрена».
     */
    public Policy approve(long agentId, long applicationId, LocalDate startDate) throws Exception {
        if (startDate == null || startDate.isBefore(LocalDate.now())) {
            throw new ValidationException("Дата начала действия договора не может быть в прошлом");
        }
        return cm.inTransaction(c -> {
            Application a = applicationDao.lockById(c, applicationId);
            if (a == null) {
                throw new ValidationException("Заявка не найдена");
            }
            if (a.getStatus() != ApplicationStatus.NEW) {
                throw new BusinessRuleException("Заявка уже рассмотрена: " + a.getStatus().getTitle());
            }
            PremiumQuote q = quote(c, a.getClientId(), a, startDate);
            Policy p = new Policy();
            p.setApplicationId(a.getId());
            p.setClientId(a.getClientId());
            p.setAgentId(agentId);
            p.setTypeId(a.getTypeId());
            p.setInsuredSum(q.getInsuredSum());
            p.setPremium(q.getPremium());
            p.setFranchise(q.getFranchise());
            p.setStartDate(startDate);
            p.setEndDate(startDate.plusMonths(a.getTermMonths()).minusDays(1));
            long policyId = policyDao.insert(c, p);
            List<Payment> schedule = InstallmentScheduler.build(policyId, q.getPremium(), a.getInstallments(),
                    startDate, a.getTermMonths());
            paymentDao.insertAll(c, schedule);
            applicationDao.decide(c, a.getId(), ApplicationStatus.APPROVED, agentId,
                    "Оформлен договор " + p.getPolicyNumber());
            return policyDao.findById(c, policyId);
        });
    }

    public Application reject(long agentId, long applicationId, String comment) throws Exception {
        String reason = Validator.required(comment, "Причина отказа");
        return cm.inTransaction(c -> {
            Application a = applicationDao.lockById(c, applicationId);
            if (a == null) {
                throw new ValidationException("Заявка не найдена");
            }
            if (a.getStatus() != ApplicationStatus.NEW) {
                throw new BusinessRuleException("Заявка уже рассмотрена: " + a.getStatus().getTitle());
            }
            applicationDao.decide(c, applicationId, ApplicationStatus.REJECTED, agentId, reason);
            return applicationDao.findById(c, applicationId);
        });
    }
}

package by.bsuir.insurance.server.service;

/** Сопровождение договоров: взносы, продление, расторжение, контроль. */
public class PolicyService {
    private static final Logger LOG = Logger.getLogger(PolicyService.class.getName());
    /** За сколько дней до окончания договор попадает в список истекающих и может быть продлён. */
    public static final int EXPIRING_DAYS = 30;

    private final PolicyDao policyDao = new PolicyDao();
    private final PaymentDao paymentDao = new PaymentDao();
    private final ClaimDao claimDao = new ClaimDao();
    private final ClientDao clientDao = new ClientDao();
    private final InsuranceTypeDao typeDao = new InsuranceTypeDao();
    private final ApplicationDao applicationDao = new ApplicationDao();
    private final PremiumCalculator premiumCalculator = new PremiumCalculator();
    private final RefundCalculator refundCalculator = new RefundCalculator();
    private final ConnectionManager cm = ConnectionManager.getInstance();

    public ArrayList<Policy> listByClient(long clientId) throws Exception {
        return new ArrayList<>(cm.withConnection(c -> policyDao.listByClient(c, clientId)));
    }

    public ArrayList<Policy> listAll(PolicyStatus status) throws Exception {
        return new ArrayList<>(cm.withConnection(c -> policyDao.listAll(c, status)));
    }

    /** График взносов; клиент может просматривать только свои договоры. */
    public ArrayList<Payment> payments(User user, long policyId) throws Exception {
        return cm.withConnection(c -> {
            Policy p = policyDao.findById(c, policyId);
            checkAccess(user, p);
            return new ArrayList<>(paymentDao.listByPolicy(c, policyId));
        });
    }

    /** Внесение клиентом ближайшего неуплаченного взноса (UC6). */
    public Policy payInstallment(User user, long policyId) throws Exception {
        LocalDate today = LocalDate.now();
        return cm.inTransaction(c -> {
            Policy p = policyDao.lockById(c, policyId);
            checkAccess(user, p);
            if (p.getStatus() != PolicyStatus.WAITING_PAYMENT && p.getStatus() != PolicyStatus.ACTIVE
                    && p.getStatus() != PolicyStatus.SUSPENDED) {
                throw new BusinessRuleException("По договору в статусе «" + p.getStatus().getTitle()
                        + "» взносы не принимаются");
            }
            Payment next = null;
            for (Payment pm : paymentDao.listByPolicy(c, policyId)) {
                if (!pm.isPaid()) {
                    next = pm;
                    break;
                }
            }
            if (next == null) {
                throw new BusinessRuleException("Все взносы по договору уже уплачены");
            }
            paymentDao.markPaid(c, policyId, next.getInstallmentNo(), today);
            applyRules(c, policyDao.findById(c, policyId), today);
            return policyDao.findById(c, policyId);
        });
    }

    /**
     * Продление договора (UC9): создаётся новый договор того же клиента и вида на тот же срок,
     * начинающийся на следующий день после окончания текущего; премия рассчитывается заново.
     */
    public Policy renew(long agentId, long policyId) throws Exception {
        return cm.inTransaction(c -> {
            Policy old = policyDao.lockById(c, policyId);
            if (old == null) {
                throw new ValidationException("Договор не найден");
            }
            LocalDate today = LocalDate.now();
            boolean expiringSoon = (old.getStatus() == PolicyStatus.ACTIVE)
                    && !old.getEndDate().isAfter(today.plusDays(EXPIRING_DAYS));
            if (old.getStatus() != PolicyStatus.EXPIRED && !expiringSoon) {
                throw new BusinessRuleException("Продлить можно истёкший договор или действующий договор, "
                        + "срок которого заканчивается в течение " + EXPIRING_DAYS + " дней");
            }
            if (policyDao.hasRenewal(c, old)) {
                throw new BusinessRuleException("Договор уже продлён");
            }
            int term = (int) ChronoUnit.MONTHS.between(old.getStartDate(), old.getEndDate().plusDays(1));
            LocalDate start = old.getEndDate().plusDays(1);
            if (start.isBefore(today.plusDays(1))) {
                start = today.plusDays(1);
            }
            Application params = new Application();
            params.setTypeId(old.getTypeId());
            params.setRequestedSum(old.getInsuredSum());
            params.setTermMonths(term);
            params.setFranchisePercent(old.getFranchise().signum() == 0 ? 0
                    : old.getFranchise().multiply(new java.math.BigDecimal(100))
                    .divide(old.getInsuredSum(), 0, java.math.RoundingMode.HALF_UP).intValue());
            params.setInstallments(1);
            Application source = old.getApplicationId() == null ? null : applicationDao.findById(c, old.getApplicationId());
            params.setObjectDescription(source == null ? "" : source.getObjectDescription());
            if (source != null && term % source.getInstallments() == 0) {
                params.setInstallments(source.getInstallments());
            }
            int claims = claimDao.countPaidClaims(c, old.getClientId(), start.minusYears(2), start);
            PremiumQuote q = premiumCalculator.calculate(typeDao.findById(c, old.getTypeId()), params,
                    clientDao.findById(c, old.getClientId()), start, claims);
            Policy p = new Policy();
            p.setClientId(old.getClientId());
            p.setAgentId(agentId);
            p.setTypeId(old.getTypeId());
            p.setInsuredSum(q.getInsuredSum());
            p.setPremium(q.getPremium());
            p.setFranchise(q.getFranchise());
            p.setStartDate(start);
            p.setEndDate(start.plusMonths(term).minusDays(1));
            long id = policyDao.insert(c, p);
            paymentDao.insertAll(c, InstallmentScheduler.build(id, q.getPremium(), params.getInstallments(), start, term));
            return policyDao.findById(c, id);
        });
    }

    /** Предварительный расчёт возврата при расторжении. */
    public RefundCalculation previewRefund(long policyId, LocalDate date) throws Exception {
        return cm.withConnection(c -> refund(c, checkTerminable(policyDao.findById(c, policyId)), date));
    }

    private RefundCalculation refund(Connection c, Policy p, LocalDate date) throws Exception {
        return refundCalculator.calculate(p, p.getPaidAmount(), claimDao.sumPayouts(c, p.getId()), date);
    }

    /** Досрочное расторжение с возвратом части премии (UC10). */
    public Policy terminate(long policyId) throws Exception {
        LocalDate today = LocalDate.now();
        return cm.inTransaction(c -> {
            Policy p = checkTerminable(policyDao.lockById(c, policyId));
            RefundCalculation r = refund(c, p, today);
            paymentDao.deleteUnpaidAfter(c, policyId, today);
            policyDao.terminate(c, policyId, LocalDateTime.now(), r.getRefund());
            return policyDao.findById(c, policyId);
        });
    }

    private Policy checkTerminable(Policy p) throws Exception {
        if (p == null) {
            throw new ValidationException("Договор не найден");
        }
        if (p.getStatus() != PolicyStatus.ACTIVE && p.getStatus() != PolicyStatus.SUSPENDED
                && p.getStatus() != PolicyStatus.WAITING_PAYMENT) {
            throw new BusinessRuleException("Расторгнуть можно только действующий, приостановленный "
                    + "или ожидающий оплаты договор");
        }
        return p;
    }

    /** Список контроля (UC11): просроченные взносы и договоры, истекающие в ближайшие 30 дней. */
    public ArrayList<ControlItem> controlList() throws Exception {
        LocalDate today = LocalDate.now();
        return cm.withConnection(c -> {
            ArrayList<ControlItem> items = new ArrayList<>(paymentDao.listOverdue(c, today));
            for (Policy p : policyDao.listExpiring(c, today, EXPIRING_DAYS)) {
                if (policyDao.hasRenewal(c, p)) {
                    continue;
                }
                items.add(new ControlItem(ControlItem.Kind.EXPIRING_POLICY, p.getId(), p.getPolicyNumber(),
                        p.getClientName(), clientDao.findById(c, p.getClientId()).getPhone(), p.getEndDate(),
                        p.getPremium(), ChronoUnit.DAYS.between(today, p.getEndDate())));
            }
            return items;
        });
    }

    /** Пересчёт состояний всех изменяемых договоров на текущую дату. Возвращает число изменённых. */
    public int refreshStatuses() throws Exception {
        LocalDate today = LocalDate.now();
        int changed = cm.inTransaction(c -> {
            int n = 0;
            for (Policy p : policyDao.listChangeable(c)) {
                if (applyRules(c, p, today)) {
                    n++;
                }
            }
            return n;
        });
        LOG.info("Пересчёт состояний договоров: изменено " + changed);
        return changed;
    }

    private boolean applyRules(Connection c, Policy p, LocalDate today) throws Exception {
        List<Payment> payments = paymentDao.listByPolicy(c, p.getId());
        PolicyStatus next = PolicyStatusRules.evaluate(p, payments, today);
        if (next != p.getStatus()) {
            policyDao.updateStatus(c, p.getId(), next);
            return true;
        }
        return false;
    }

    static void checkAccess(User user, Policy p) throws Exception {
        if (p == null) {
            throw new ValidationException("Договор не найден");
        }
        if (user.getRole() == Role.CLIENT && p.getClientId() != user.getPersonId()) {
            throw new AuthException("Нет доступа к чужому договору");
        }
    }
}

package by.bsuir.insurance.server.service;

/** Заявления о страховых случаях и их урегулирование. */
public class ClaimService {
    private final ClaimDao claimDao = new ClaimDao();
    private final PolicyDao policyDao = new PolicyDao();
    private final PaymentDao paymentDao = new PaymentDao();
    private final PayoutCalculator calculator = new PayoutCalculator();
    private final ConnectionManager cm = ConnectionManager.getInstance();

    /** Заявление клиента о страховом случае (UC7). */
    public Claim report(User user, Claim claim) throws Exception {
        Validator.notFuture(claim.getIncidentDate(), "Дата события");
        Validator.positive(claim.getDamageAmount(), "Размер ущерба");
        claim.setDescription(Validator.required(claim.getDescription(), "Описание события"));
        claim.setReportDate(LocalDate.now());
        return cm.inTransaction(c -> {
            Policy p = policyDao.findById(c, claim.getPolicyId());
            PolicyService.checkAccess(user, p);
            if (!p.getStatus().allowsClaims()) {
                throw new BusinessRuleException("По договору в статусе «" + p.getStatus().getTitle()
                        + "» заявления не принимаются");
            }
            return claimDao.findById(c, claimDao.insert(c, claim));
        });
    }

    public ArrayList<Claim> listByClient(long clientId) throws Exception {
        return new ArrayList<>(cm.withConnection(c -> claimDao.listByClient(c, clientId)));
    }

    public ArrayList<Claim> listPending() throws Exception {
        return new ArrayList<>(cm.withConnection(c -> claimDao.listByStatus(c, ClaimStatus.REPORTED)));
    }

    public ArrayList<Claim> listAll() throws Exception {
        return new ArrayList<>(cm.withConnection(claimDao::listAll));
    }

    /** Предварительный расчёт выплаты для показа агенту. */
    public PayoutDecision preview(long claimId, BigDecimal assessedDamage) throws Exception {
        return cm.withConnection(c -> decide(c, claimDao.findById(c, claimId), assessedDamage));
    }

    /**
     * Урегулирование страхового случая (UC8): расчёт выплаты, фиксация решения и,
     * если страховая сумма исчерпана, перевод договора в состояние «Исполнен».
     */
    public Claim settle(long agentId, long claimId, BigDecimal assessedDamage, String comment) throws Exception {
        return cm.inTransaction(c -> {
            Claim claim = claimDao.lockById(c, claimId);
            PayoutDecision d = decide(c, claim, assessedDamage);
            String text = (comment == null || comment.trim().isEmpty()) ? d.getReason() : comment.trim() + ". " + d.getReason();
            claimDao.decide(c, claimId, d.isApproved() ? ClaimStatus.APPROVED : ClaimStatus.REJECTED,
                    Money.round(assessedDamage), d.getAmount(), agentId, text);
            if (d.isExhaustsSum()) {
                policyDao.updateStatus(c, claim.getPolicyId(), PolicyStatus.FULFILLED);
            }
            return claimDao.findById(c, claimId);
        });
    }

    private PayoutDecision decide(Connection c, Claim claim, BigDecimal assessedDamage) throws Exception {
        if (claim == null) {
            throw new ValidationException("Страховой случай не найден");
        }
        if (claim.getStatus() != ClaimStatus.REPORTED) {
            throw new BusinessRuleException("Решение по страховому случаю уже принято");
        }
        Validator.positive(assessedDamage, "Оценённый ущерб");
        Policy p = policyDao.lockById(c, claim.getPolicyId());
        return calculator.calculate(p, paymentDao.listByPolicy(c, p.getId()), claim, assessedDamage,
                claimDao.sumPayouts(c, p.getId()));
    }
}
